ocation", "Risk_Details": "If applicable in document", "Risk_Insured_Amount": 0.00, "Risk_Premium_Amount": 0.00, "Risk_Deductible": 0.00, "Risk_Rate": 0.00, "Category_Group": "II. Storage Risks", "Category_Group_Type": "Stock Throughput", "PerPersonLimit": 0.00, "AggregateLimit": 0.00 } ] } ] }
